import{_ as a,o as E,c as s,a4 as e}from"./chunks/framework.B-wJupoK.js";const t="/assets/image-20250104194004233.DXkXfmHX.png",i="/assets/image-20250104191515226.Di8eDNjz.png",r="/assets/image-20250104194756416.D2CguRmI.png",A="/assets/0FB7BC5A.BdqdgnS3.png",p="/assets/image-20250104191602656.jRl3J9fr.png",o="/assets/image-20250104191831548.BBr5_IkG.png",g="/assets/0FB7BC5A.BdqdgnS3.png",m="/assets/image-20250104192327298.IBo2YPsA.png",B="/assets/image-20250104192519324.DAcga4jh.png",u=JSON.parse('{"title":"鸿蒙元服务实战-笑笑五子棋（1）","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/鸿蒙元服务实战-笑笑五子棋/鸿蒙元服务实战-笑笑五子棋（1）/鸿蒙元服务实战-笑笑五子棋（1）.md","filePath":"鸿蒙开发技巧/鸿蒙元服务实战-笑笑五子棋/鸿蒙元服务实战-笑笑五子棋（1）/鸿蒙元服务实战-笑笑五子棋（1）.md","lastUpdated":1736065340000,"__rawMarkdown":"# 鸿蒙元服务实战-笑笑五子棋（1）\\n\\n## 前言\\n\\n作为鸿蒙应用的深度开发者都应该知道，经历了**波澜壮阔12月风波**，到2025年新的开始。鸿蒙应用开发的热度算是下去一些了。\\n\\n这里就把之前上架了的元服务-《笑笑五子棋》给开源分享出来。\\n\\n## 笑笑五子棋\\n\\n笑笑五子棋的名字比较朴素，因为**笑笑**这个名字是我女儿的名字，这也应该是众多屌丝程序员独有的浪漫了吧（自嗨）。\\n\\n界面风格如下：\\n\\n![image-20250104194004233](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%881%EF%BC%89.assets/image-20250104194004233.png)\\n\\n\\n\\n## 笑笑五子棋的数据\\n\\n当然，笑笑五子棋也是拿到了元服务的基础激励的。\\n\\n![image-20250104191515226](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%881%EF%BC%89.assets/image-20250104191515226.png)\\n\\n---\\n\\n目前是付款中状态：\\n\\n\\n\\n![image-20250104194756416](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%881%EF%BC%89.assets/image-20250104194756416.png)\\n\\n> 这个金额是假的！！![img](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%881%EF%BC%89.assets/0FD04174.png)\\n\\n上架时间是 **2025-12-09**。\\n\\n![image-20250104191602656](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%881%EF%BC%89.assets/image-20250104191602656.png)\\n\\n基础激励的要求是 7天活跃设备100。也是达到了。\\n\\n![image-20250104191831548](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%881%EF%BC%89.assets/image-20250104191831548.png)\\n\\n这个日活**dddd** ![img](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%881%EF%BC%89.assets/0FB7BC5A.png)\\n\\n然后比较开心的是最近这个应用还上了**鸿蒙负一屏的休闲分类菜单**中。\\n\\n![image-20250104192327298](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%881%EF%BC%89.assets/image-20250104192327298.png)\\n\\n\\n\\n出现比较靠前的位置后，活跃数据更加出众了。\\n\\n![image-20250104192519324](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%881%EF%BC%89.assets/image-20250104192519324.png)\\n\\n\\n\\n然后因为是个人开发者，所以在对接广告上存在困难。如果是用企业资质的话，引入广告还是很容易的。\\n\\n\\n\\n## 相关的技术\\n\\n主要用到了以下技术\\n\\n1. ArkTS API 12\\n2. Canvas\\n3. 元服务独有的AtomicServiceTabs\\n4. 卡片开发\\n5. 元服务的创建\\n6. 元服务的上架\\n\\n\\n\\n## 小结\\n\\n这篇文章主要是介绍了这个应用的周边，下一篇文章主要围绕代码技术开展。\\n\\n如果你兴趣想要了解更多的鸿蒙应用开发细节和最新资讯，欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。\\n\\n\\n\\n"}'),l={name:"鸿蒙开发技巧/鸿蒙元服务实战-笑笑五子棋/鸿蒙元服务实战-笑笑五子棋（1）/鸿蒙元服务实战-笑笑五子棋（1）.md"};function _(C,n,c,d,h,F){return E(),s("div",null,[...n[0]||(n[0]=[e("",31)])])}const b=a(l,[["render",_]]);export{u as __pageData,b as default};
